from pathlib import Path
import sys,json,numpy as np
W=Path(__file__).resolve().parent;sys.path.insert(0,str(W/'backend'))
from numerics import load_arrays,numpy_force
original=load_arrays();m=np.load(W/'conforming_split.npz');x=m['x'];t=m['tets'];D=(x[t[:,1:]]-x[t[:,0]][:,None]).transpose(0,2,1);parent=m['parent_tet'];fixed=m['fixed'];z={'x':x,'tet_indices':t,'tet_poses':np.linalg.inv(D),'tet_mu':original['tet_mu'][parent],'tet_lambda':original['tet_lambda'][parent],'tet_damping':original['tet_damping'][parent],'tet_activations':original['tet_activations'][parent]};zero=np.zeros_like(x);f=numpy_force(z,x,zero);vel=np.tile([.01,-.02,.03],(len(x),1));translation=numpy_force(z,x,vel)-f;affine=-(x-x.mean(0))*.01;damp=numpy_force(z,x,affine)-f;free=np.ones(len(x),bool);free[fixed]=False;rest_acc=np.linalg.norm(f[free],axis=1)/m['mass'][free]
out={'scope':'Independent rest/material controls for conforming split input, WITHOUT active cohesive force assembly; not a dynamic pass','rest_force_norm_N':float(np.linalg.norm(f)),'maximum_rest_force_N':float(np.linalg.norm(f,axis=1).max()),'maximum_free_rest_acceleration_m_s2':float(rest_acc.max()),'common_translation_added_force_norm_N':float(np.linalg.norm(translation)),'affine_damping_power_W':float(np.sum(damp*affine)),'maximum_rest_edge_matrix_condition_number':float(np.linalg.cond(D).max()),'minimum_positive_nodal_mass_kg':float(m['mass'][m['mass']>0].min()),'coefficient_mapping_matches_parent_tets':all(np.array_equal(z[name],original[name][parent]) for name in ['tet_mu','tet_lambda','tet_damping','tet_activations']),'passed':bool(np.isfinite(f).all() and np.linalg.norm(f)<1e-8 and np.linalg.norm(translation)<1e-9 and np.sum(damp*affine)<=0),'next_dynamic_gate':'Initialize the actual cohesive/contact law and validate this new assembly, including small-cell numerical cost, before shallow cutting; intact hold does not substitute.'};(W/'split_material_preflight_result.json').write_text(json.dumps(out,indent=2));print(json.dumps(out,indent=2));assert out['passed']
